ALTER DATABASE CURRENT SET CHANGE_TRACKING = ON (CHANGE_RETENTION = 2 DAYS, AUTO_CLEANUP = ON);
ALTER TABLE dbo.Products ENABLE CHANGE_TRACKING WITH (TRACK_COLUMNS_UPDATED = ON);

DECLARE @last BIGINT = 1041;  -- saved from previous sync
SELECT ct.ProductId, ct.SYS_CHANGE_OPERATION, p.Name, p.Price
FROM CHANGETABLE(CHANGES dbo.Products, @last) AS ct
LEFT JOIN dbo.Products AS p ON p.ProductId = ct.ProductId;
SELECT CHANGE_TRACKING_CURRENT_VERSION();  -- save for next time

EXEC sys.sp_cdc_enable_db;
EXEC sys.sp_cdc_enable_table @source_schema = N'dbo', @source_name = N'Orders',
     @role_name = NULL, @supports_net_changes = 1;

DECLARE @from BINARY(10) = sys.fn_cdc_get_min_lsn(N'dbo_Orders'),
        @to   BINARY(10) = sys.fn_cdc_get_max_lsn();
SELECT __$operation, OrderId, Status
FROM cdc.fn_cdc_get_all_changes_dbo_Orders(@from, @to, N'all');

CREATE MASTER KEY ENCRYPTION BY PASSWORD = '<strong password>';
CREATE DATABASE SCOPED CREDENTIAL EhCred WITH IDENTITY = 'Managed Identity';
EXEC sys.sp_enable_event_stream;
EXEC sys.sp_create_event_stream_group
     @stream_group_name      = N'OrdersStream',
     @destination_type       = N'AzureEventHubs',
     @destination_location   = N'contoso-ns.servicebus.windows.net:9093/orders',
     @destination_credential = EhCred,
     @partition_key_scheme   = N'None';
EXEC sys.sp_add_object_to_event_stream_group N'OrdersStream', N'dbo.Orders';

[Function("ProductChanged")]
public static void Run(
    [SqlTrigger("[dbo].[Products]", "SqlConnectionString")]
    IReadOnlyList<SqlChange<Product>> changes, FunctionContext ctx)
{
    foreach (var c in changes)
        ctx.GetLogger("p").LogInformation("{op} {id}", c.Operation, c.Item.ProductId);
}
